function render(){graphStates.clear();const [r,id]=route.split('/');if(r==='home')home();else if(r==='learn'||r==='modules')modulePage(r==='learn');else if(r==='lesson')lesson(id);else if(r==='practice'||r==='quizzes')setup(r==='quizzes');else if(r==='session')session?questionPage():go('practice');else if(r==='targeted')targetedPage();else if(r==='results')resultsPage();else if(r==='progress')progressPage();else if(r==='formulas')formulasPage();else if(r==='saved')savedPage();else if(r==='search')searchPage();else home()}
