 function expr(){let v=term();while(t[pos]==='+'||t[pos]==='-'){const op=t[pos++],r=term();v=op==='+'?v+r:v-r}return v}
 function term(){let v=unary();while(t[pos]==='*'||t[pos]==='/'){const op=t[pos++],r=unary();v=op==='*'?v*r:v/r}return v}
 function unary(){if(t[pos]==='+'){pos++;return unary()}if(t[pos]==='-'){pos++;return-unary()}return power()}
 function power(){let v=atom();if(t[pos]==='^'){pos++;v=v**unary()}return v}
 function atom(){if(++depth>80)throw Error('Expression is too long.');let v,token=t[pos++];if(token==='('){v=expr();if(t[pos++]!==')')throw Error('Close each parenthesis.')}else if(functions[token]){if(t[pos++]!=='(')throw Error('Use '+token+'(x), with parentheses.');v=functions[token](expr());if(t[pos++]!==')')throw Error('Close the function parentheses.')}else if(token==='pi')v=Math.PI;else if(token==='e')v=Math.E;else if(token==='x'||token==='t')v=xValue;else if(token!==undefined&&/^(\d|\.)/.test(token))v=Number(token);else throw Error('Check the expression.');depth--;return v}
